create table if not exists public.traveling_tokens (id uuid primary key default gen_random_uuid(),token_code text not null unique,nfc_public_token uuid not null unique default gen_random_uuid(),activation_pin_hash text,owner_id uuid references auth.users(id) on delete set null,creator_id uuid references auth.users(id) on delete set null,name text,mission text,status text not null default 'unclaimed' check (status in ('unclaimed','draft','in_circulation','in_transit','retired')),current_box_id uuid references public.physical_treasure_boxes(id) on delete set null,activated_at timestamptz,circulation_started_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.traveling_token_stops (id uuid primary key default gen_random_uuid(),traveling_token_id uuid not null references public.traveling_tokens(id) on delete cascade,physical_box_id uuid not null references public.physical_treasure_boxes(id) on delete restrict,stop_number integer not null check (stop_number>0),arrived_at timestamptz not null default now(),arrived_by uuid references auth.users(id) on delete set null,departed_at timestamptz,departed_by uuid references auth.users(id) on delete set null,distance_from_previous_miles numeric(12,2),created_at timestamptz not null default now(),unique(traveling_token_id,stop_number));
create index if not exists traveling_token_stops_token_idx on public.traveling_token_stops(traveling_token_id,stop_number);
alter table public.traveling_tokens enable row level security; alter table public.traveling_token_stops enable row level security;
create or replace function public.get_owned_traveling_tokens() returns table(token_id uuid,token_code text,nfc_public_token uuid,name text,mission text,status text,current_box_code text,circulation_started_at timestamptz,stop_count bigint,total_miles numeric) language sql stable security definer set search_path='' as $$ select t.id,t.token_code,t.nfc_public_token,t.name,t.mission,t.status,b.serial_code,t.circulation_started_at,count(s.id),coalesce(sum(s.distance_from_previous_miles),0) from public.traveling_tokens t left join public.physical_treasure_boxes b on b.id=t.current_box_id left join public.traveling_token_stops s on s.traveling_token_id=t.id where t.owner_id=auth.uid() group by t.id,b.serial_code order by t.created_at desc; $$;
create or replace function public.get_traveling_token_public(p_nfc_public_token uuid) returns table(token_id uuid,token_code text,name text,mission text,status text,planter_first_name text,circulation_started_at timestamptz,stop_count bigint,total_miles numeric,current_box_code text) language sql stable security definer set search_path='' as $$ select t.id,t.token_code,t.name,t.mission,t.status,coalesce(p.first_name,'A Trailblazer'),t.circulation_started_at,count(s.id),coalesce(sum(s.distance_from_previous_miles),0),b.serial_code from public.traveling_tokens t left join public.profiles p on p.id=t.creator_id left join public.traveling_token_stops s on s.traveling_token_id=t.id left join public.physical_treasure_boxes b on b.id=t.current_box_id where t.nfc_public_token=p_nfc_public_token and t.status in ('in_circulation','in_transit') group by t.id,p.first_name,b.serial_code; $$;
revoke all on function public.get_owned_traveling_tokens() from public; grant execute on function public.get_owned_traveling_tokens() to authenticated; revoke all on function public.get_traveling_token_public(uuid) from public; grant execute on function public.get_traveling_token_public(uuid) to anon,authenticated;